        load = 1;
        data = 10'd2;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin errors = errors + 1; end

        // Count to 1
        @(negedge clk);
        load = 0;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin errors = errors + 1; end

        // Before hitting 0, reload with 1
        @(negedge clk);
        load = 1;
        data = 10'd1;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) begin errors = errors + 1; end

        // Count should reach 0 on the next cycle
        @(negedge clk);
        load = 0;
        @(posedge clk);
        #1;
        if (tc !== 1'b1) begin errors = errors + 1; end

